  /* 노선이 상자를 나눠 쓸 때 — 코드만 이어 붙인다 (데이터는 한 벌) */
  var ALIAS = { /* dolomiti_loop: "alps_traverse" */ };

  var CACHE = {};
  var KIND = { l: 'lake', b: 'border', r: 'river', n: 'land' };   /* ⭐ 0825a — 뭍이 붙었다 */

  /* 델타 정수 → [[위도, 경도], …]. 첫 점만 절대이고 나머지는 차이다 */
  function decode(blob) {
    var out = { lake: [], border: [], river: [], land: [] };
    var lines = blob.split("\n"), i, j, t, k, body, parts, la, lo, seg, p;
    for (i = 0; i < lines.length; i++) {
      t = lines[i]; if (!t) continue;
      k = KIND[t.charAt(0)]; if (!k) continue;
      body = t.slice(2); parts = body.split(" ");
      la = 0; lo = 0; seg = [];
      for (j = 0; j < parts.length; j++) {
        p = parts[j].split(",");
        la += +p[0]; lo += +p[1];
        seg.push([la / 10000, lo / 10000]);
      }
      if (seg.length >= 2) out[k].push(seg);
    }
    return out;
  }

  function get(code) {
    var key = ALIAS[code] || code;
    if (CACHE[key]) return CACHE[key];
    if (!BLOB[key]) return null;
    try { CACHE[key] = decode(BLOB[key]); } catch (e) {
      console.warn("[EG] 밑그림을 못 풀었습니다:", e); return null;
    }
    return CACHE[key];
  }
  function has(code) { return !!BLOB[ALIAS[code] || code]; }

  window.EGMapNE = { get: get, has: has, version: VERSION };
